// Builds packages/explain/src/explainers.gen.ts from docs/EXPLAINERS.md (run `make explainers`).
// Runs with Node's TypeScript type stripping: `node --experimental-strip-types scripts/build_explainers.ts`.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { parseExplainers } from "../packages/explain/src/parse.ts";

const root = fileURLToPath(new URL("..", import.meta.url));
const entries = parseExplainers(readFileSync(`${root}docs/EXPLAINERS.md`, "utf8"));
const body = [
  "// GENERATED by scripts/build_explainers.ts from docs/EXPLAINERS.md. Do not edit; run `make explainers`.",
  "",
  `export const explainers = ${JSON.stringify(entries, null, 2)} as const;`,
  "",
].join("\n");
writeFileSync(`${root}packages/explain/src/explainers.gen.ts`, body);
console.log(`wrote packages/explain/src/explainers.gen.ts (${Object.keys(entries).length} keys)`);
